import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import Button from '../components/ui/Button';
import '../styles/pages/MapViewPage.css';

// Importamos las imágenes de césped con la ruta correcta (Assets con A mayúscula)
import grass1 from '../assets/images/tiles/grass/grass_01.png';
import grass2 from '../assets/images/tiles/grass/grass_02.png';
import grass3 from '../assets/images/tiles/grass/grass_03.png';
import grass4 from '../assets/images/tiles/grass/grass_04.png';

// Array de imágenes de césped para seleccionar aleatoriamente
const grassTiles = [grass1, grass2, grass3, grass4];

interface Tile {
  id: string;
  type: string;
  image: string;
}

const MapViewPage: React.FC = () => {
  const navigate = useNavigate();
  const [map, setMap] = useState<Tile[][]>([]);
  const [loading, setLoading] = useState(true);
  
  // Configuración del mapa
  const mapWidth = 20;
  const mapHeight = 15;
  
  useEffect(() => {
    // Generar mapa aleatorio con los diferentes tipos de césped
    generateRandomMap();
  }, []);
  
  const generateRandomMap = () => {
    setLoading(true);
    
    const newMap: Tile[][] = [];
    
    for (let y = 0; y < mapHeight; y++) {
      const row: Tile[] = [];
      for (let x = 0; x < mapWidth; x++) {
        // Seleccionar aleatoriamente una imagen de césped
        const randomIndex = Math.floor(Math.random() * grassTiles.length);
        const tileImage = grassTiles[randomIndex];
        
        row.push({
          id: `tile-${x}-${y}`,
          type: 'grass',
          image: tileImage
        });
      }
      newMap.push(row);
    }
    
    setMap(newMap);
    setLoading(false);
  };
  
  const handleRefreshMap = () => {
    generateRandomMap();
  };
  
  const handleBackToMenu = () => {
    navigate('/menu');
  };
  
  if (loading) {
    return <div className="loading-screen">Generando mapa...</div>;
  }
  
  return (
    <div className="map-view-page">
      <div className="map-view-header">
        <h1>Visor de Mapa</h1>
        <div className="map-controls">
          <Button onClick={handleRefreshMap}>Generar Nuevo Mapa</Button>
          <Button onClick={handleBackToMenu}>Volver al Menú</Button>
        </div>
      </div>
      
      <div className="map-container">
        <div 
          className="game-map-grid" 
          style={{ 
            gridTemplateColumns: `repeat(${mapWidth}, 48px)`,
            gridTemplateRows: `repeat(${mapHeight}, 48px)`
          }}
        >
          {map.flat().map((tile) => (
            <div key={tile.id} className="map-tile">
              <img src={tile.image} alt={`Tile ${tile.type}`} className="tile-image" />
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default MapViewPage;
